contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 seedAmount) public payable {
        // record observable state before call
        bool beforeInitialized = c.initialized(); if (__ESBMC_reverted()) return;
        uint256 beforeMarket = c.marketDrugs(); if (__ESBMC_reverted()) return;
        uint256 beforeBalance = address(c).balance;

        // call seedMarket and capture whether it reverted
        bool reverted;
        c.seedMarket(seedAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // record observable state after call
        bool afterInitialized = c.initialized(); if (__ESBMC_reverted()) return;
        uint256 afterMarket = c.marketDrugs(); if (__ESBMC_reverted()) return;
        uint256 afterBalance = address(c).balance;

        // If the call did not revert then it must have been that beforeMarket == 0,
        // and the call sets initialized to true and marketDrugs to seedAmount,
        // and it does not change the contract's ether balance.
        // If it reverted then beforeMarket was nonzero (require prevented it).
        assert((!reverted && beforeMarket == 0 && afterInitialized == true && afterMarket == seedAmount && afterBalance == beforeBalance)
               || (reverted && beforeMarket != 0));
    }
    receive() external payable {}
}

