pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherCartel c;

    function setUp() public {
        c = new EtherCartel();
    }

    function _run(uint256 seedAmount) internal {
        bool beforeInitialized;
        try c.initialized() returns (bool __r) { beforeInitialized = __r; } catch { return; }
        uint256 beforeMarket;
        try c.marketDrugs() returns (uint256 __r) { beforeMarket = __r; } catch { return; }
        uint256 beforeBalance = address(c).balance;
        bool reverted;
        try c.seedMarket(seedAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        bool afterInitialized;
        try c.initialized() returns (bool __r) { afterInitialized = __r; } catch { return; }
        uint256 afterMarket;
        try c.marketDrugs() returns (uint256 __r) { afterMarket = __r; } catch { return; }
        uint256 afterBalance = address(c).balance;
        assertTrue((!reverted && beforeMarket == 0 && afterInitialized == true && afterMarket == seedAmount && afterBalance == beforeBalance)
               || (reverted && beforeMarket != 0));
    }

    function testFuzz_run(uint256 seedAmount) public {
        _run(seedAmount);
    }

    receive() external payable {}
}
